mapper.select:
SELECT ACCT_NO, BUSI_ACCT_NO, GROUP_CONCAT(PORTFOLIO_ID order by PORTFOLIO_ID SEPARATOR ',') PORTFOLIO_ID, GROUP_CONCAT(PORTFOLIO_NAME order by PORTFOLIO_ID SEPARATOR ',') PORTFOLIO_NAME, SUM(unmatch) unmatchedNum, sum(matched) matchNum from ( SELECT DISTINCT ACCT_NO, BUSI_ACCT_NO, PORTFOLIO_ID, PORTFOLIO_NAME, case when MATCH_SEQNO is null then count(1) else 0 end unmatch, case when MATCH_SEQNO is not null then count(1) else 0 end matched FROM ( SELECT T1.ACCT_NO, IFNULL(t3.BUSI_ACCT_NO, t3.ACCT_NO) BUSI_ACCT_NO, t2.PORTFOLIO_ID, t2.PORTFOLIO_NAME, T7.MATCH_SEQNO FROM TRD_FIN_PRODUCT_DEAL_TOTAL T4 LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TT ON TT.P_TOTLE_TRADE_ID = T4.TOTLE_TRADE_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T5 ON T4.TOTLE_TRADE_ID = T5.TOTLE_TRADE_ID left join PTL_CAPACCT_INFO T1 ON T4.PORTFOLIO_ID = T1.PORTFOLIO_ID and t4.CCY = T1.CCY LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN PA_PTL_PORTFOLIO P3 ON P3.PORTFOLIO_ID = T2.PORTFOLIO_ID inner JOIN STL_CAPACCT_INFO T3 ON T3.ACCT_NO = T1.ACCT_NO AND T3.CCY = T1.CCY LEFT JOIN LQD_PIPELINE_MATCH T7 ON IFNULL(TT.TOTLE_TRADE_ID, T4.TOTLE_TRADE_ID) = T7.SYS_TRADE_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = T4.SEC_MANAGE_ACCT_ID AND SSAI.TRD_ACCT_CCY = T4.CCY LEFT JOIN STL_PAY_ORDERS SPO ON T4.TOTLE_TRADE_ID = SPO.TRADE_ID OR TT.TOTLE_TRADE_ID = SPO.TRADE_ID WHERE T1.ACCT_TYPE = #{A01} AND P3.IS_GUARANTEE = #{NO} AND SPO.MY_ACCT_NO IS NOT NULL AND (SPO.COUNTER_ACCT_NO IS NULL OR SPO.MY_ACCT_NO != SPO.COUNTER_ACCT_NO) AND T4.PORTFOLIO_ID IS NOT NULL AND T4.TRADE_STATUS = #{TRADE_STATUS_01} AND (T4.IS_CANCEL IS NULL OR T4.IS_CANCEL = #{NO}) AND (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE05},#{PA_BUSINESS_TYPE03}, #{PA_BUSINESS_TYPE06}, #{PA_BUSINESS_TYPE07},#{PA_BUSINESS_TYPE100}, #{PA_BUSINESS_TYPE42}, #{PA_BUSINESS_TYPE03}, #{PA_BUSINESS_TYPE08}, #{PA_BUSINESS_TYPE137}, #{PA_BUSINESS_TYPE138}, #{PA_BUSINESS_TYPE43}) or (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE52}, #{PA_BUSINESS_TYPE76}) AND (SSAI.SEC_ACCT_SOURCE = #{AS_02} or SSAI.REGIST_ORG not in (#{ROI_01}, #{ROI_02}))) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE09}) AND (SSAI.SEC_ACCT_SOURCE = #{AS_02} or SSAI.REGIST_ORG not in (#{ROI_01}, #{ROI_02}))) )
#{item} AND EXISTS (SELECT 1 from STL_PAY_ORDERS T6 WHERE T4.TOTLE_TRADE_ID = T6.TRADE_ID AND (T6.COUNTER_ACCT_NO IS NULL OR T6.MY_ACCT_NO != T6.COUNTER_ACCT_NO) #{item})
UNION ALL
SELECT T1.ACCT_NO, IFNULL(t3.BUSI_ACCT_NO, t3.ACCT_NO) BUSI_ACCT_NO, t2.PORTFOLIO_ID, t2.PORTFOLIO_NAME, T7.MATCH_SEQNO FROM TRD_PRODUCT_DEAL T4 LEFT JOIN PA_TRD_PRODUCT_DEAL T5 ON T4.TRADE_ID = T5.TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD T8 ON T4.TRADE_ID = T8.TRADE_ID left join PTL_CAPACCT_INFO T1 ON T8.PORTFOLIO_ID = T1.PORTFOLIO_ID and t4.CCY = T1.CCY LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN PA_PTL_PORTFOLIO P3 ON P3.PORTFOLIO_ID = T2.PORTFOLIO_ID inner JOIN STL_CAPACCT_INFO T3 ON T3.ACCT_NO = T1.ACCT_NO AND T3.CCY = T1.CCY LEFT JOIN LQD_PIPELINE_MATCH T7 ON T4.TRADE_ID = T7.SYS_TRADE_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = T4.SEC_MANAGE_ACCT_ID AND SSAI.TRD_ACCT_CCY = T4.CCY LEFT JOIN STL_PAY_ORDERS SPO ON T4.TRADE_ID = SPO.TRADE_ID WHERE T1.ACCT_TYPE = #{A01} AND P3.IS_GUARANTEE = #{NO} AND SPO.MY_ACCT_NO IS NOT NULL AND (SPO.COUNTER_ACCT_NO IS NULL OR SPO.MY_ACCT_NO != SPO.COUNTER_ACCT_NO) AND T8.PORTFOLIO_ID IS NOT NULL AND T4.TRADE_STATUS = #{TRADE_STATUS_01} AND (T4.IS_CANCEL IS NULL OR T4.IS_CANCEL = #{NO}) AND (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE12}, #{PA_BUSINESS_TYPE17}, #{PA_BUSINESS_TYPE29}, #{PA_BUSINESS_TYPE33}, #{PA_BUSINESS_TYPE21}, #{PA_BUSINESS_TYPE25}, #{PA_BUSINESS_TYPE97}, #{PA_BUSINESS_TYPE16}, #{PA_BUSINESS_TYPE63}, #{PA_BUSINESS_TYPE65}) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE19}, #{PA_BUSINESS_TYPE75}) AND (SSAI.SEC_ACCT_SOURCE = #{AS_02} or SSAI.REGIST_ORG not in (#{ROI_01}, #{ROI_02}))) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE09}) AND (T4.TRADE_MARKET IN (#{TP03}, #{TP04}) AND T4.TRADE_MARKET_MODE = #{STM_01})) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE09}) AND (T4.TRADE_MARKET IN (#{TP01}) AND T4.TRADE_MARKET_MODE = #{STM_01} AND T4.TRADE_PLAT = #{SHARES_TRADE_PLATFORM_99})) )
#{item} AND EXISTS (SELECT 1 from STL_PAY_ORDERS T6 WHERE T4.TRADE_ID = T6.TRADE_ID AND (T6.COUNTER_ACCT_NO IS NULL OR T6.MY_ACCT_NO != T6.COUNTER_ACCT_NO) #{item})
UNION ALL
SELECT T1.ACCT_NO, IFNULL(t3.BUSI_ACCT_NO, t1.ACCT_NO) BUSI_ACCT_NO, t1.PORTFOLIO_ID, t2.PORTFOLIO_NAME, T7.MATCH_SEQNO FROM STL_DVP_ORDERS T4 left join PTL_CAPACCT_INFO T1 ON T4.PORTFOLIO_ID = T1.PORTFOLIO_ID and t4.CCY = T1.CCY AND T1.ACCT_NO = T4.MY_ACCT_NO LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID inner JOIN STL_CAPACCT_INFO T3 ON T3.ACCT_NO = T1.ACCT_NO AND T3.CCY = T1.CCY LEFT JOIN LQD_PIPELINE_MATCH T7 ON T4.ORDER_ID = T7.SYS_TRADE_ID WHERE T4.PS = #{PS02}
#{item}
) GROUP BY ACCT_NO, BUSI_ACCT_NO,PORTFOLIO_ID, PORTFOLIO_NAME, MATCH_SEQNO ) GROUP BY ACCT_NO, BUSI_ACCT_NO

SELECT '${sysOrEn}' sysOrEn, T4.TOTLE_TRADE_ID sysSeqNo, '${YES}' IS_TOTAL_TRADE, case when t9.MATCH_SEQNO is null then '${NO}' else '${YES}' end matchStatus, PAY_ORDERS.ORDER_STATUS operateType, IFNULL(T4.P_TOTLE_TRADE_ID, T4.TOTLE_TRADE_ID) bizCode, t5.PA_BUSS_TYPE paBizType, t4.PORTFOLIO_ID, t7.PORTFOLIO_NAME, t6.FINPROD_ID finprodId, t6.FINPROD_MARKET_ID, IFNULL(t6.FINPROD_ABBR, t6.FINPROD_NAME) finprodName, PAY_ORDERS.SETTLE_AMT, DATE_FORMAT(PAY_ORDERS.SETTLE_DATE, '%Y-%m-%d') settleDateTheory, DATE_FORMAT(PAY_ORDERS.SETTLE_DATE, '%Y-%m-%d') SETTLE_DATE, t8.COUNTER_NAME counter, t4.CCY, t4.SEC_MANAGE_ACCT_ID, T5.THEORY_AMT settleAmtTheory, '${STATUS_VALID_05}' statusValid, 0 todo, NULL workflowId, NULL wflWorkflowId, T4.PS PS, T6.PROFIT_TYPE profitType FROM TRD_FIN_PRODUCT_DEAL_TOTAL T4 LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T5 ON T4.TOTLE_TRADE_ID = T5.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T6 ON T4.FINPROD_ID = T6.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T7 ON T4.PORTFOLIO_ID = T7.PORTFOLIO_ID LEFT JOIN (SELECT * FROM STL_PAY_ORDERS T5 WHERE T5.ORDER_ID = (SELECT MAX(T52.ORDER_ID) FROM STL_PAY_ORDERS T52 WHERE T5.TRADE_ID = T52.TRADE_ID)) PAY_ORDERS ON T4.TOTLE_TRADE_ID = PAY_ORDERS.TRADE_ID
LEFT JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = T4.SEC_MANAGE_ACCT_ID AND SSAI.TRD_ACCT_CCY = T4.CCY
LEFT JOIN MST_COUNTER_PARTY T8 ON T4.COUNTER_ID = T8.COUNTER_ID LEFT JOIN LQD_PIPELINE_MATCH T9 ON T4.TOTLE_TRADE_ID = T9.SYS_TRADE_ID
WHERE (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE05},#{PA_BUSINESS_TYPE03}, #{PA_BUSINESS_TYPE06}, #{PA_BUSINESS_TYPE07},#{PA_BUSINESS_TYPE100}, #{PA_BUSINESS_TYPE42}, #{PA_BUSINESS_TYPE137}, #{PA_BUSINESS_TYPE03}, #{PA_BUSINESS_TYPE08}, #{PA_BUSINESS_TYPE43}) or (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE52}, #{PA_BUSINESS_TYPE76}) AND (SSAI.SEC_ACCT_SOURCE = #{AS_02} or SSAI.REGIST_ORG not in (#{ROI_01}, #{ROI_02}))) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE09}) AND (SSAI.SEC_ACCT_SOURCE = #{AS_02} or SSAI.REGIST_ORG not in (#{ROI_01}, #{ROI_02}))) )
AND T4.TRADE_STATUS = #{TRADE_STATUS_01} AND (T4.IS_CANCEL IS NULL OR T4.IS_CANCEL = #{NO}) AND NOT EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TT WHERE TT.P_TRADE_ID = T4.TOTLE_TRADE_ID) AND (PAY_ORDERS.COUNTER_ACCT_NO IS NULL OR PAY_ORDERS.MY_ACCT_NO != PAY_ORDERS.COUNTER_ACCT_NO) AND T4.PORTFOLIO_ID IS NOT NULL
#{item}
#{item}
AND PAY_ORDERS.ORDER_STATUS = #{operateType}
AND PAY_ORDERS.SETTLE_DATE >= STR_TO_DATE(#{cashDateStart}, '%Y-%m-%d')
AND PAY_ORDERS.SETTLE_DATE <= STR_TO_DATE(#{cashDateEnd}, '%Y-%m-%d')
and PAY_ORDERS.MY_ACCT_NO = #{acctNo}
AND EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where IFNULL(T4.P_TOTLE_TRADE_ID, T4.TOTLE_TRADE_ID) = LPM.SYS_TRADE_ID)
AND NOT EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where IFNULL(T4.P_TOTLE_TRADE_ID, T4.TOTLE_TRADE_ID) = LPM.SYS_TRADE_ID)
#{item}
UNION ALL
SELECT '${sysOrEn}' sysOrEn, T3.TRADE_ID sysSeqNo, '${NO}' IS_TOTAL_TRADE, case when t9.MATCH_SEQNO is null then '${NO}' else '${YES}' end matchStatus, PAY_ORDERS.ORDER_STATUS operateType, case when T5.PA_BUSS_TYPE = '${PA_BUSINESS_TYPE65}' THEN PAY_ORDERS.ORDER_ID ELSE T3.TRADE_ID END bizCode, t5.PA_BUSS_TYPE paBizType, t4.PORTFOLIO_ID, t7.PORTFOLIO_NAME, t6.FINPROD_ID finprodId, t6.FINPROD_MARKET_ID, IFNULL(t6.FINPROD_ABBR, t6.FINPROD_NAME) finprodName, PAY_ORDERS.SETTLE_AMT, DATE_FORMAT(PAY_ORDERS.SETTLE_DATE, '%Y-%m-%d') settleDateTheory, DATE_FORMAT(PAY_ORDERS.SETTLE_DATE, '%Y-%m-%d') SETTLE_DATE, t8.COUNTER_NAME counter, t3.CCY, t3.SEC_MANAGE_ACCT_ID, null settleAmtTheory, '${STATUS_VALID_05}' statusValid, 0 todo, NULL workflowId, NULL wflWorkflowId, T3.PS PS, T6.PROFIT_TYPE profitType FROM TRD_PRODUCT_DEAL T3 LEFT JOIN TRD_PRODUCT_DEAL_ADD T4 ON T3.TRADE_ID = T4.TRADE_ID LEFT JOIN PA_TRD_PRODUCT_DEAL T5 ON T4.TRADE_ID = T5.TRADE_ID LEFT JOIN FIN_PRODUCT T6 ON T3.FINPROD_ID = T6.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T7 ON T4.PORTFOLIO_ID = T7.PORTFOLIO_ID LEFT JOIN (SELECT * FROM STL_PAY_ORDERS T5 WHERE T5.ORDER_ID = (SELECT MAX(T52.ORDER_ID) FROM STL_PAY_ORDERS T52 WHERE T5.TRADE_ID = T52.TRADE_ID)) PAY_ORDERS ON T3.TRADE_ID = PAY_ORDERS.TRADE_ID
LEFT JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = T3.SEC_MANAGE_ACCT_ID AND SSAI.TRD_ACCT_CCY = T3.CCY
LEFT JOIN MST_COUNTER_PARTY T8 ON T3.COUNTER_ID = T8.COUNTER_ID LEFT JOIN LQD_PIPELINE_MATCH T9 ON T3.TRADE_ID = T9.SYS_TRADE_ID
WHERE (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE12}, #{PA_BUSINESS_TYPE17}, #{PA_BUSINESS_TYPE29}, #{PA_BUSINESS_TYPE33}, #{PA_BUSINESS_TYPE21}, #{PA_BUSINESS_TYPE25}, #{PA_BUSINESS_TYPE97}, #{PA_BUSINESS_TYPE16}, #{PA_BUSINESS_TYPE63}, #{PA_BUSINESS_TYPE65}) OR (T5.PA_BUSS_TYPE = #{PA_BUSINESS_TYPE86} AND PAY_ORDERS.IS_NEED_SEND =#{YES}) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE19}, #{PA_BUSINESS_TYPE75}) AND (SSAI.SEC_ACCT_SOURCE = #{AS_02} or SSAI.REGIST_ORG not in (#{ROI_01}, #{ROI_02}))) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE09}) AND (T3.TRADE_MARKET IN (#{TP03}, #{TP04}) AND T3.TRADE_MARKET_MODE = #{STM_01})) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE09}) AND (T3.TRADE_MARKET IN (#{TP01}) AND T3.TRADE_MARKET_MODE = #{STM_01} AND T3.TRADE_PLAT = #{SHARES_TRADE_PLATFORM_99})) )
AND T3.TRADE_STATUS = #{TRADE_STATUS_01} AND (T3.IS_CANCEL IS NULL OR T3.IS_CANCEL = #{NO}) AND NOT EXISTS (SELECT 1 FROM WFL_TRD_PRODUCT_DEAL TT WHERE TT.P_TRADE_ID = T3.TRADE_ID) AND (PAY_ORDERS.COUNTER_ACCT_NO IS NULL OR PAY_ORDERS.MY_ACCT_NO != PAY_ORDERS.COUNTER_ACCT_NO) AND T4.PORTFOLIO_ID IS NOT NULL
#{item}
#{item}
AND PAY_ORDERS.ORDER_STATUS = #{operateType}
AND PAY_ORDERS.SETTLE_DATE >= STR_TO_DATE(#{cashDateStart}, '%Y-%m-%d')
AND PAY_ORDERS.SETTLE_DATE <= STR_TO_DATE(#{cashDateEnd}, '%Y-%m-%d')
and PAY_ORDERS.MY_ACCT_NO = #{acctNo}
AND EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where T3.TRADE_ID = LPM.SYS_TRADE_ID)
AND NOT EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where T3.TRADE_ID = LPM.SYS_TRADE_ID)
#{item}
UNION ALL
SELECT '${sysOrEn}' sysOrEn, T3.ORDER_ID sysSeqNo, 'DVP' IS_TOTAL_TRADE, case when t9.MATCH_SEQNO is null then '${NO}' else '${YES}' end matchStatus, T3.ORDER_STATUS operateType, T3.ORDER_ID bizCode, '${PA_BUSINESS_TYPE81}' paBizType, T3.PORTFOLIO_ID, t7.PORTFOLIO_NAME, NULL finprodId, NULL FINPROD_MARKET_ID, NULL finprodName, T3.SETTLE_AMT, DATE_FORMAT(T3.SETTLE_DATE, '%Y-%m-%d') settleDateTheory, DATE_FORMAT(T3.SETTLE_DATE, '%Y-%m-%d') SETTLE_DATE, NULL counter, t3.CCY, '${PA_BUSINESS_TYPE81}' SEC_MANAGE_ACCT_ID, NULL settleAmtTheory, '${STATUS_VALID_05}' statusValid, 0 todo, NULL workflowId, NULL wflWorkflowId, T3.PS, null profitType FROM STL_DVP_ORDERS T3 LEFT JOIN PTL_PORTFOLIO T7 ON T3.PORTFOLIO_ID = T7.PORTFOLIO_ID LEFT JOIN LQD_PIPELINE_MATCH T9 ON T3.ORDER_ID = T9.SYS_TRADE_ID WHERE T3.PS = #{PS02}
#{item}
AND T3.ORDER_STATUS = #{operateType}
AND T3.SETTLE_DATE >= STR_TO_DATE(#{cashDateStart}, '%Y-%m-%d')
AND T3.SETTLE_DATE <= STR_TO_DATE(#{cashDateEnd}, '%Y-%m-%d')
and T3.MY_ACCT_NO = #{acctNo}
AND EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where T3.ORDER_ID = LPM.SYS_TRADE_ID)
AND NOT EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where T3.ORDER_ID = LPM.SYS_TRADE_ID)

SELECT '${sysOrEn}' sysOrEn, T1.SEQNO enSeqNo, case when t9.MATCH_SEQNO is null then '${NO}' else '${YES}' end matchStatus, DATE_FORMAT(T1.CDATE,'%Y-%m-%d') settleDate, T1.PRINAMT settleAmt, T1.SELLER counterAcctNo, T1.ACCOUNT, T1.SELLERNAME counterAcctName, T1.PS, T1."USAGE" "usage", T1.REMARK FROM inf_tru_cashflow_daily T1 LEFT JOIN LQD_PIPELINE_MATCH T9 ON T1.SEQNO = T9.TRU_SEQ_NO
T1.PS = #{CD_FLOW_FLAG_01} AND T1.ACCOUNT = #{busiAcctNo} AND T1.SELLER NOT IN ( SELECT t2.ACCT_NO FROM STL_SEC_ACCT_INFO T3 INNER JOIN STL_CAPACCT_INFO T2 ON T3.TRD_ACCT_ID = T2.ACCT_NO where T3.TRADE_PLACE = '01')
AND T1.SELLER = #{counterAcctNo}
AND DATE_FORMAT(T1.CDATE,'%Y-%m-%d') >= #{arriveDateStart}
AND DATE_FORMAT(T1.CDATE,'%Y-%m-%d') <= #{arriveDateEnd}
AND T1.PRINAMT >= #{arriveAmtMin}
AND T1.PRINAMT <= #{arriveAmtMax}
AND EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where T1.SEQNO = LPM.TRU_SEQ_NO)
AND NOT EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where T1.SEQNO = LPM.TRU_SEQ_NO)
order by T1.PRINAMT asc
